begin;
do $$
declare boss uuid:=gen_random_uuid();emp uuid:=gen_random_uuid();owner_id uuid;sid uuid:=gen_random_uuid();c uuid;j uuid;result jsonb;denied boolean;before_members jsonb;before_workers jsonb;
begin
 insert into auth.users(id,email,email_confirmed_at) values(boss,boss||'@service.test.invalid',now()),(emp,emp||'@service.test.invalid',now());perform set_config('request.jwt.claim.sub',boss::text,true);c:=public.create_company_for_edition('Service controls fixture','essential');update public.companies set is_test=true,billing_mode='test_simulated',billing_status='active',seat_limit=10 where id=c;insert into private.essential_test_plans(company_id,snapshot) select c,to_jsonb(p) from public.essential_plans p where id='essential_pro';insert into public.company_members(company_id,user_id,role) values(c,emp,'employee');select default_punch_job_id into j from public.companies where id=c;
 select jsonb_agg(to_jsonb(m) order by user_id) into before_members from public.company_members m where company_id=c;select jsonb_agg(to_jsonb(w) order by id) into before_workers from public.company_workers w where company_id=c;
 select user_id into owner_id from private.platform_owner;insert into auth.sessions(id,user_id,aal,not_after) values(sid,owner_id,'aal2',clock_timestamp()+interval '1 hour');perform set_config('request.jwt.claim.sub',owner_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'session_id',sid,'aal','aal2')::text,true);execute 'set local role authenticated';
 denied:=false;begin perform public.platform_set_company_service(c,true,null,0,'wrong','Synthetic hold');exception when others then denied:=true;end;if not denied then raise exception 'Missing exact confirmation accepted';end if;
 result:=public.platform_set_company_service(c,true,null,0,c::text,'Synthetic commercial hold');if result->>'effective_status'<>'restricted' or (result->>'version')::integer<>1 then raise exception 'Suspension ineffective';end if;
 denied:=false;begin perform public.platform_set_company_service(c,false,null,0,c::text,'Stale controls');exception when others then denied:=true;end;if not denied then raise exception 'Stale controls accepted';end if;
 result:=public.platform_company_detail(c,'Synthetic service verification');if result->>'effective_billing_status'<>'restricted' or not (result->'service_controls'->>'suspended')::boolean then raise exception 'Detail missing effective hold';end if;
 perform set_config('request.jwt.claim.sub',boss::text,true);if private.can_administer(c) then raise exception 'Suspended manager could administer';end if;
 perform set_config('request.jwt.claim.sub',emp::text,true);result:=public.sync_punch_event(gen_random_uuid(),c,'in',clock_timestamp(),false,j,null,null,null,null);if result->>'sync_status'<>'synced' then raise exception 'Commercial hold interrupted employee punch: %',result;end if;perform public.sync_punch_event(gen_random_uuid(),c,'out',clock_timestamp(),false,null,null,null,null,null);
 perform set_config('request.jwt.claim.sub',owner_id::text,true);result:=public.platform_set_company_service(c,false,null,1,c::text,'Synthetic release');if result->>'effective_status'<>'active' then raise exception 'Release did not restore calculated base state';end if;
 execute 'reset role';insert into private.essential_billing_accounts(company_id,subscription_id,status,paid_through,first_unpaid_at) values(c,'sub_fixture_'||c,'past_due',clock_timestamp()-interval '41 days',clock_timestamp()-interval '40 days');execute 'set local role authenticated';
 result:=public.platform_set_company_service(c,false,60,2,c::text,'Synthetic extended grace');if result->>'effective_status'<>'grace' then raise exception 'Client grace override ignored';end if;
 result:=public.platform_set_company_service(c,false,0,3,c::text,'Synthetic immediate restriction');if result->>'effective_status'<>'restricted' then raise exception 'Zero grace ignored';end if;
 result:=public.platform_set_company_service(c,false,null,4,c::text,'Synthetic default restoration');if result->>'effective_status'<>'restricted' then raise exception 'Release manufactured payment';end if;
 execute 'reset role';if before_members is distinct from (select jsonb_agg(to_jsonb(m) order by user_id) from public.company_members m where company_id=c) or before_workers is distinct from (select jsonb_agg(to_jsonb(w) order by id) from public.company_workers w where company_id=c) then raise exception 'Service control changed member or worker';end if;
 if (select subscription_id from private.essential_billing_accounts where company_id=c)<>'sub_fixture_'||c or (select status from private.essential_billing_accounts where company_id=c)<>'past_due' then raise exception 'Service control changed Stripe state';end if;
 perform set_config('request.jwt.claim.sub',boss::text,true);execute 'set local role authenticated';denied:=false;begin perform public.platform_set_company_service(c,false,null,5,c::text,'Unauthorized boss action');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Boss altered platform controls';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',owner_id::text,true);delete from auth.sessions where id=sid;execute 'set local role authenticated';denied:=false;begin perform public.platform_set_company_service(c,false,null,5,c::text,'Revoked owner action');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Revoked platform session accepted';end if;execute 'reset role';
end $$;
rollback;
